CREATE    VIEW [synapse_fo].[vwTransType]
AS
SELECT tab.TransType, tab.Description FROM(VALUES
	(0, 'None'),
	(1, 'Transfer'),
	(2, 'Sales order'),
	(3, 'Purchase order'),
	(4, 'Inventory'),
	(5, 'Production'),
	(6, 'Project'),
	(7, 'Interest'),
	(8, 'Customer'),
	(9, 'Foreign currency revaluation'),
	(10, 'Totaled'),
	(11, 'Payroll'),
	(12, 'Fixed assets'),
	(13, 'Collection letter'),
	(14, 'Vendor'),
	(15, 'Payment'),
	(16, 'Sales tax'),
	(17, 'Bank'),
	(18, 'Ledger accounting currency conversion'),
	(19, 'Bill of exchange'),
	(20, 'Promissory note'),
	(21, 'Cost accounting'),
	(22, 'Labor'),
	(23, 'Fee'),
	(24, 'Settlement'),
	(25, 'Allocation'),
	(26, 'Elimination'),
	(27, 'Cash discount'),
	(28, 'Overpayment/underpayment'),
	(29, 'Penny difference'),
	(30, 'Intercompany settlement'),
	(31, 'Purchase requisition'),
	(32, 'Inflation adjustment'),
	(33, 'Prepayment application'),
	(34, 'Ledger reporting currency conversion'),
	(79, 'Fixed assets (Russia)'),
	(80, 'AR amortization'),
	(81, 'Deferrals'),
	(82, 'AP amortization'),
	(83, 'Advance adjustment'),
	(84, 'Tax agent'),
	(85, 'Currency conversion gain/loss'),
	(100, 'Rebate credit note processing'),
	(101, 'Rebate pass to AP'),
	(35, 'Write off'),
	(36, 'General journal'),
	(251, 'Underpayment write off')
